<script setup lang="ts">
import type { NotificationItem } from '~/composables/useNotifications'

defineProps<{
  filteredNotifications: NotificationItem[]
  newNotifications: NotificationItem[]
  earlierNotifications: NotificationItem[]
  confirmingActionItem: { id: string; action: 'Accept' | 'Decline'; item: NotificationItem } | null
}>()

defineEmits<{
  (e: 'mark-read', item: NotificationItem): void
  (e: 'action-primary', item: NotificationItem): void
  (e: 'action-secondary', item: NotificationItem): void
  (e: 'confirm-guard-rail', action: 'Accept' | 'Decline', item: NotificationItem): void
  (e: 'cancel-guard-rail'): void
}>()

// Safely sanitize and format markdown bold tags (**text**) into white highlighted text
const formatSubtitle = (text?: string): string => {
  if (!text) return ''
  const sanitized = text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;')

  return sanitized.replace(/\*\*(.*?)\*\*/g, '<strong class="text-white font-semibold">$1</strong>')
}
</script>

